                                                                                                                                                                                     (1, 'Dvostruka aukcija sa ogranicenim informacijama 001', 'Eksperiment ispituje odluke ucesnika u simuliranom trzistu kroz kontrolisane runde i promenljive informacije.', 'Izmeriti uticaj pravila igre, budzeta i dostupnih informacija na odluke ucesnika u eksperimentu 001.', 17, 6375.25, 1, 'Ucesnici dobijaju uloge, pocetni kapital i odluke donose u 6 rundi. Nije dozvoljena komunikacija osim kada pravila to eksplicitno dozvole.', 'Kontrolisani uslovi: broj kupaca 5, broj prodavaca 4, promenljiv nivo informacija 1.', 'Mere se profit, efikasnost alokacije, vreme odluke, stepen saradnje i odstupanje od ravnotezne cene.'),
                                                                                                                                                                                     (2, 'Simulacija trzista rada sa minimalnom cenom 002', 'Eksperiment ispituje odluke ucesnika u simuliranom trzistu kroz kontrolisane runde i promenljive informacije.', 'Izmeriti uticaj pravila igre, budzeta i dostupnih informacija na odluke ucesnika u eksperimentu 002.', 22, 7750.50, 2, 'Ucesnici dobijaju uloge, pocetni kapital i odluke donose u 7 rundi. Nije dozvoljena komunikacija osim kada pravila to eksplicitno dozvole.', 'Kontrolisani uslovi: broj kupaca 6, broj prodavaca 5, promenljiv nivo informacija 2.', 'Mere se profit, efikasnost alokacije, vreme odluke, stepen saradnje i odstupanje od ravnotezne cene.'),
